public void testQueryPointAllocResultWhenNormalThenSuccess() throws ServiceException {
    List<ProvisionPackage> provisionPackages = Arrays.asList(createMockProvisionPackage("package", 1, 100.0, 0));
    Mockito.when(packageMgrMapper.queryPackages()).thenReturn(provisionPackages);
    Mockito.when(dataDbMapper.getAllocConfigValueByName(Mockito.anyString())).thenReturn("1");
    Mockito.when(liveAllocSpaceTaskDbMapper.queryPackagesByCodes(Mockito.any()))
        .thenReturn(List.of(new PackageInfo()));
    ThirdPointAllocationQueryResult thirdPointAllocationQueryResult = new ThirdPointAllocationQueryResult();
    thirdPointAllocationQueryResult.setIntentFeasibilityCheckReport(new PointExpectationExplorationResult());
    Mockito.when(inferenceService.queryThirdPointAllocResult(Mockito.any()))
        .thenReturn(thirdPointAllocationQueryResult);
    ThirdPointAllocationQueryResult result = thirdPointAllocationServiceDelegate.queryPointAllocResult(
        thirdPointAllocationQueryParam);
    Assert.assertNotNull(result.getIntentFeasibilityCheckReport());
}

@Test
public void testQueryPointAllocResultWhenAllocThenSuccess() throws ServiceException {
    List<ProvisionPackage> provisionPackages = Arrays.asList(createMockProvisionPackage("package", 1, 100.0, 0));
    Mockito.when(packageMgrMapper.queryPackages()).thenReturn(provisionPackages);
    Mockito.when(dataDbMapper.getAllocConfigValueByName("tocAllocEva.POINT_ALLOC_SWITCH")).thenReturn("1");
    Mockito.when(liveAllocSpaceTaskDbMapper.queryPackagesByCodes(Mockito.any()))
        .thenReturn(List.of(new PackageInfo()));
